#include <bits/stdc++.h>
using namespace std;

class mcf_graph {
public:
    struct Edge {
        int to, rev;
        long long cap, cost;
        Edge(int t, int r, long long c, long long co) : to(t), rev(r), cap(c), cost(co) {}
    };

    int n;
    vector<vector<Edge>> g;
    vector<pair<int,int>> pos;
    vector<long long> dual, dist;
    vector<int> pv, pe;
    vector<bool> vis;

    mcf_graph(int n_) : n(n_), g(n_) {}

    int add_edge(int from, int to, long long cap, long long cost) {
        int m = pos.size();
        pos.emplace_back(from, g[from].size());
        g[from].emplace_back(to, g[to].size(), cap, cost);
        g[to].emplace_back(from, g[from].size()-1, 0, -cost);
        return m;
    }

    bool _dual_ref(int s, int t) {
        dist.assign(n, LLONG_MAX);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        typedef pair<long long, int> P;
        priority_queue<P, vector<P>, greater<P>> pq;
        dist[s] = 0;
        pq.emplace(0, s);

        while (!pq.empty()) {
            P p = pq.top(); pq.pop();
            int v = p.second;
            if (p.first != dist[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (int i = 0; i < g[v].size(); ++i) {
                Edge &e = g[v][i];
                if (e.cap == 0 || vis[e.to]) continue;
                long long cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    pq.emplace(dist[e.to], e.to);
                }
            }
        }
        if (!vis[t]) return false;

        for (int v = 0; v < n; ++v) {
            if (vis[v]) {
                dual[v] -= dist[t] - dist[v];
            }
        }
        return true;
    }

    vector<pair<long long, long long>> slope(int s, int t, long long flow_limit = 1LL<<60) {
        dual.assign(n, 0);
        long long flow = 0, cost = 0, prev_cost = -1;
        vector<pair<long long, long long>> result;
        result.emplace_back(flow, cost);
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            long long c = flow_limit - flow;
            for (int v = t; v != s; v = pv[v]) {
                c = min(c, g[pv[v]][pe[v]].cap);
            }
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
            }
            long long d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) {
                result.pop_back();
            }
            result.emplace_back(flow, cost);
            prev_cost = cost;
        }
        return result;
    }

    pair<long long, long long> flow(int s, int t, long long flow_limit = 1LL<<60) {
        return slope(s, t, flow_limit).back();
    }
};

int main() {
