int give(vector<vector<int>> l1, vector<vector<int>> l2) {
    int ans = 0;
    vector<int> curr1(2, 0), curr2(2, 0); // [count, type]
    while (!l1.empty() || !l2.empty()) {
        if (curr1[0] == 0) {
            if (l1.empty()) break;
            curr1 = l1.back();
            l1.pop_back();
        }
