int getWonMaxFast(vector<int> inputA, vector<int> inputB) {
    int wins[3] = {0};
    for (int i = 0; i < 3; ++i) {
        int good = (i + 1) % 3;
        wins[i] = min(inputA[i], inputB[good]);
        inputA[i] -= wins[i];
        inputB[good] -= wins[i];
    }
    return wins[0] + wins[1] + wins[2];
}

int getLostMaxFast(const vector<int>& inputA, const vector<int>& inputB) {
    vector<pair<int,int>> waysToLose = {{0,2}, {1,0}, {2,1}, {0,0}, {1,1}, {2,2}};
    sort(waysToLose.begin(), waysToLose.end());
    int maxLost = 0;
    do {
        vector<int> inputACopy = inputA;
        vector<int> inputBCopy = inputB;
        int losts[3] = {0};
        for (const auto& way : waysToLose) {
            int lost_add = min(inputACopy[way.first], inputBCopy[way.second]);
            inputACopy[way.first] -= lost_add;
            inputBCopy[way.second] -= lost_add;
            losts[way.first] += lost_add;
        }
        int lostSum = losts[0] + losts[1] + losts[2];
        if (lostSum > maxLost) maxLost = lostSum;
    } while (next_permutation(waysToLose.begin(), waysToLose.end()));
    return maxLost;
}

