#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void solve(int round, vector<int>& firstperson, vector<int>& secondperson) {
    // Compute "max win"
    int win = 0;
    // Append first element of secondperson to the end (making size 4)
    secondperson.push_back(secondperson[0]);
    for (int i = 0; i < 3; ++i) {
        int findless;
        if (firstperson[i] <= secondperson[i+1]) {
            findless = firstperson[i];
        } else {
            findless = secondperson[i+1];
        }
        win += findless;
    }
    // Remove the appended element (restore size 3)
    secondperson.pop_back();

    // Compute "min win" (reduce firstperson)
    // Insert secondperson[2] at the beginning (making size 4)
    secondperson.insert(secondperson.begin(), secondperson[2]);
    for (int i = 0; i < 3; ++i) {
        if (firstperson[i] > 0) {
            int diff = min(firstperson[i], secondperson[i]);
            firstperson[i] -= diff;
            secondperson[i] -= diff;
            if (firstperson[i] > 0) {
                diff = min(firstperson[i], secondperson[i+1]);
                firstperson[i] -= diff;
                secondperson[i+1] -= diff;
            }
        }
    }
    // Output the result
    cout << (firstperson[0] + firstperson[1] + firstperson[2]) << " " << win << endl;
}

