    vector<int> firstperson(3);
    vector<int> secondperson(3);
    for (int i = 0; i < 3; ++i) cin >> firstperson[i];
    for (int i = 0; i < 3; ++i) cin >> secondperson[i];
    solve(round, firstperson, secondperson);
    return 0;
}

