#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;
typedef long long ll;

const ll INF = 1e18;

class Dinic {
public:
    struct Edge {
        int to, rev;
        ll cap;
        Edge(int to, int rev, ll cap) : to(to), rev(rev), cap(cap) {}
    };

    int n;
    vector<vector<Edge>> graph;
    vector<int> level, it;

    Dinic(int n) : n(n), graph(n), level(n), it(n) {}

    void add_edge(int from, int to, ll cap) {
        graph[from].emplace_back(to, (int)graph[to].size(), cap);
        graph[to].emplace_back(from, (int)graph[from].size() - 1, 0);
    }

    void bfs(int s) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (const Edge &e : graph[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }

    ll dfs(int v, int t, ll f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)graph[v].size(); ++i) {
            Edge &e = graph[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                ll d = dfs(e.to, t, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    graph[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }

    ll flow(int s, int t) {
        ll flow = 0;
        while (true) {
            bfs(s);
            if (level[t] < 0) return flow;
            fill(it.begin(), it.end(), 0);
            ll f;
            while ((f = dfs(s, t, INF)) > 0) {
                flow += f;
            }
        }
    }
};

int main() {
    const int M = 3;
    int N;
    cin >> N;
    vector<int> A(M), B(M);
    for (int i = 0; i < M; ++i) cin >> A[i];
    for (int i = 0; i < M; ++i) cin >> B[i];

    ll ans1 = 0;
    for (int i = 0; i < M; ++i) {
        ans1 += min(A[i], B[(i+1)%M]);
    }

    Dinic dinic(2*M+2);
    int s = 2*M;
    int t = 2*M+1;
    for (int i = 0; i < M; ++i) {
        dinic.add_edge(s, i, N);
        dinic.add_edge(M+i, t, B[i]);
        // draw
        dinic.add_edge(i, M+i, A[i]);
        // lose: i -> M+((i-1)%M)
        dinic.add_edge(i, M+((i-1+M)%M), A[i]);
    }

    ll ans2 = N - dinic.flow(s, t);
    cout << ans2 << " " << ans1 << endl;

    return 0;
}

