int main() {
    int64_t n, mod;
    std::cin >> n >> mod;
    std::vector<int64_t> mem(n + 1, 0);
    int64_t su = 1;
    mem[1] = 1;

    for (int64_t i = 2; i <= n; ++i) {
        int64_t sq = static_cast<int64_t>(std::sqrt(i)) + 1;
        int64_t cur = su;

        for (int64_t f = 2; f < sq; ++f) {
            cur = (cur + mem[i / f]) % mod;
        }

        int64_t be = i;
        for (int64_t j = 1; j <= i / sq; ++j) {
            int64_t nxt = i / (j + 1);
            cur = (cur + (be - nxt) * mem[j]) % mod;
            be = nxt;
        }

        su = (su + cur) % mod;
        mem[i] = cur;
    }

    std::cout << mem[n] << std::endl;
    return 0;
}

