#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, M;
    cin >> n >> M;

    // D[i] will contain all divisors d (2 <= d < i) such that d divides i
    vector<vector<int>> D(n + 1);
    for (int d = 2; d <= n; ++d) {
        for (int dst = 2 * d; dst <= n; dst += d) {
            D[dst].push_back(d);
        }
    }

    vector<long long> F(n + 1);
    F[1] = 1;
    if (n >= 2) {
        F[2] = 2;
    }

    for (int x = 3; x <= n; ++x) {
        long long val = (2 * F[x - 1] + F[x / (x - 1)]) % M;
        long long S = 0;
        for (int d : D[x]) {
            if (2 <= d && d <= x - 2) {
                S += F[x / d] - F[(x - 1) / d];
            }
        }
        // Note: S may be negative, adjust modulo
        S %= M;
        if (S < 0) S += M;
        F[x] = (val + S) % M;
    }

    cout << (F[n] % M) << endl;

    return 0;
}

