#include <bits/stdc++.h>
using namespace std;

vector<int> primes;

// Precompute primes up to 6000
void init_primes() {
    for (int p = 2; p < 6000; ++p) {
        bool is_prime = true;
        for (int p2 : primes) {
            if (p2 * p2 > p) break;
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) primes.push_back(p);
    }
}

// Factor n into prime exponents using precomputed primes
map<int,int> factor(int n) {
    map<int,int> d;
    for (int p : primes) {
        if (p * p > n) break;
        if (n % p == 0) {
            int cnt = 0;
            while (n % p == 0) {
                n /= p;
                ++cnt;
            }
            d[p] = cnt;
        }
    }
    if (n > 1) d[n] = 1;
    return d;
}

// Generate all divisors of n from its prime factorization
vector<long long> factors(int n) {
    map<int,int> d = factor(n);
    vector<long long> answer = {1};
    for (auto& kv : d) {
        int p = kv.first;
        int exp = kv.second;
        vector<long long> new_answer;
        for (long long x : answer) {
            long long mult = 1;
            for (int i = 0; i <= exp; ++i) {
                new_answer.push_back(x * mult);
                mult *= p;
            }
        }
        answer = new_answer;
    }
    return answer;
}

long long process(int n, int m) {
    vector<long long> f(n+1);
    f[0] = 0;
    if (n >= 1) f[1] = 1;
    if (n >= 2) f[2] = 2;
    for (int i = 3; i <= n; ++i) {
        f[i] = (2 * f[i-1]) % m;
        vector<long long> divs = factors(i);
        for (long long x : divs) {
            if (x >= 2 && x <= i) {
                long long diff = (f[i / x] - f[(i-1) / x] + m) % m;
                f[i] = (f[i] + diff) % m;
            }
        }
        // f[i] already modulo m
    }
    return f[n];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    init_primes();
    int n, m;
    cin >> n >> m;
    cout << process(n, m) << '\n';
    return 0;
}

