#include <bits/stdc++.h>
using namespace std;

const long long M = 1000000007;

long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void process() {
    long long P, K;
    cin >> P >> K;

    vector<long long> k(P);
    for (long long x = 0; x < P; x++) {
        k[x] = (K * x) % P;
    }

    if (K == 0) {
        cout << mod_pow(P, P - 1, M) << '\n';
        return;
    }

    vector<int> f(P, 0);
    vector<int> c(P, 0);
    long long ans = 1;

    for (long long i = 0; i < P; i++) {
        if (f[i]) continue;

        long long cnt = 1;
        long long u = i;
        f[u] = 1;

        while (f[k[u]] == 0) {
            u = k[u];
            f[u] = 1;
            cnt++;
        }

        c[cnt]++;
    }

    for (long long i = 1; i < P; i++) {
        if (c[i] != 0) {
            long long cnt = i * c[i] + (i > 1 ? 1 : 0);
            ans = (ans * mod_pow(cnt, c[i], M)) % M;
        }
    }

    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T = 1;
    while (T--) {
        process();
    }

    return 0;
}

