                s = q.substr(0, qn-1) + "at";
            } else {
                s = q;
            }
            n = s.size();
        }

        // third if: ends with "dot", but not starting with "dot" or "at"
        if (n >= 3 && s.substr(n-3) == "dot" &&
            !(n >= 3 && s.substr(0,3) == "dot") &&
            !(n >= 2 && s.substr(0,2) == "at")) {
            string t = s.substr(0, n-3);
            size_t pos;
            while ((pos = t.find("dot")) != string::npos)
                t.replace(pos, 3, ".");
            string l = t;
            size_t b = l.find("at");
            string q = l.substr(0, b) + "@" + l.substr(b+2);
            s = q + "dot";
            n = s.size();
        }

        // fourth if: ends with "at", but not starting with "dot" or "at"
        if (n >= 2 && s.substr(n-2) == "at" &&
