#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int first_half = n / 2 + n % 2;   // size of first part
    int second_half = n / 2;          // size of second part

    vector<int> b;
    // enumerate all subsets of first half
    for (int i = 0; i < (1 << first_half); ++i) {
        int t = 0;
        int k = i;
        for (int j = 0; j < 20; ++j) {
            if (k & 1) {
                t += a[j];
            }
            k >>= 1;
        }
        b.push_back(t % m);
    }
    sort(b.begin(), b.end());

    int otv = 0;
    // enumerate all subsets of second half
    for (int i = 0; i < (1 << second_half); ++i) {
        int t = 0;
        int k = i;
        for (int j = 0; j < 20; ++j) {
            if (k & 1) {
                t += a[first_half + j];
            }
            k >>= 1;
        }
        t %= m;

        int target = m - t - 1;
        auto it = lower_bound(b.begin(), b.end(), target);
        int idx = it - b.begin();

        int t2;
        if (idx < (int)b.size()) {
            t2 = b[idx];
            if (t2 > target) {
                if (idx - 1 >= 0) {
                    t2 = b[idx - 1];
                }
            }
        } else {
            t2 = b.back();
        }

        int cand1 = (t + t2) % m;
        int cand2 = (t + b.back()) % m;
        otv = max(otv, max(cand1, cand2));
    }

    cout << otv % m << endl;
    return 0;
}

