        for (int j = 0; j < size2; ++j) {
            if (mask & (1 << j)) {
                sum = (sum + a[n1 + j]) % m;
            }
        }
        a2.push_back(sum);
    }

    // sort and deduplicate a1
    sort(a1.begin(), a1.end());
    a1.erase(unique(a1.begin(), a1.end()), a1.end());

    long long ans = 0;
    for (long long i : a2) {
        // find the largest sum in a1 that is < m - i
