typedef long long ll;

int MOD;
vector<vector<unordered_map<int, ll>>> memo;

ll solve(int N, int k, int flag) {
    auto &mp = memo[N][flag];
    if (mp.find(k) != mp.end()) return mp[k];
    if (N == 1) {
        ll res;
        if (flag) res = 0;
        else res = (k < 0) ? 1 : 0;
        mp[k] = res;
        return res;
    }
    int invnum_INF = N * (N - 1) / 2;
    if (k < -invnum_INF - 1) {
        ll res = solve(N, -invnum_INF - 1, flag);
        mp[k] = res;
        return res;
