    ll res = 0;
    for (int delta = -N + 1; delta < N; ++delta) {
        if (flag && delta > 0) continue;
        int wt = min(N - delta, delta + N);
        res += solve(N - 1, k - delta, (delta == 0 && flag) ? 1 : 0) * wt;
        res %= MOD;
    }
    mp[k] = res % MOD;
    return res % MOD;
}

