    int m = n * (n - 1) / 2;

    // dp[i][j][k]
    vector<vector<vector<ll>>> dp(n + 1, vector<vector<ll>>(m + 1, vector<ll>(n + 1, 0)));
    dp[1][0][1] = 1;

    for (int i = 1; i < n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; k <= n; ++k) {
                ll a = dp[i][j][k];
                if (a == 0) continue;

                // first update: put i+1 into the set
                dp[i + 1][j + i][i + 1] = (dp[i + 1][j + i][i + 1] + a) % mod;

                // second update: shift left positions
                for (int l = 0; l < i; ++l) {
                    int nj = j + i - 1 - l;
                    dp[i + 1][nj][k] = (dp[i + 1][nj][k] + a) % mod;
                }
            }
        }
    }

    // S_dp[i][k][j] = sum_{t=0..j} dp[i][t][k] (prefix over j)
    vector<vector<vector<ll>>> S_dp(n + 1, vector<vector<ll>>(n + 1, vector<ll>(m + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int k = 0; k <= n; ++k) {
            ll a = 0;
            for (int j = 0; j <= m; ++j) {
                a = (a + dp[i][j][k]) % mod;
                S_dp[i][k][j] = a;
            }
        }
    }

    // SS_dp[i][j][k] = sum_{t=0..k} S_dp[i][t][j] (double prefix)
    vector<vector<vector<ll>>> SS_dp(n + 1, vector<vector<ll>>(m + 1, vector<ll>(n + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            ll a = 0;
            for (int k = 0; k <= n; ++k) {
                a = (a + S_dp[i][k][j]) % mod;
                SS_dp[i][j][k] = a;
            }
        }
    }

    vector<ll> ANS(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        ll ans = ( (ll)i * ANS[i - 1] ) % mod;
        for (int k = 0; k <= n; ++k) {
