typedef long long ll;
typedef vector<vector<vector<ll>>> vvv;
typedef vector<vector<ll>> vv;
typedef vector<ll> v;

ll mod;
vector<ll> fact, ifact;

ll modpow(ll a, ll e) {
    ll r = 1;
    while (e) {
        if (e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

void precompute_fact(int n) {
    fact.resize(n + 1);
    ifact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    ifact[n] = modpow(fact[n], mod - 2);
    for (int i = n - 1; i >= 0; i--) ifact[i] = ifact[i + 1] * (i + 1) % mod;
}

ll comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * ifact[k] % mod * ifact[n - k] % mod;
}

ll e_gcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll g = e_gcd(b, a % b, y, x);
    y -= a / b * x;
    return g;
}

ll mod_inv(ll a, ll m) {
    ll x, y;
    e_gcd(a, m, x, y);
    return (x % m + m) % m;
}

vector<ll> tf(int n, ll M) {
    vector<ll> C(n + 1, 0);
