int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, mod;
    cin >> n >> mod;

    long long m = (long long)n * (n - 1) / 2;
    int size = n * (n - 1) + 1;

    vector<long long> dp_prev(size, 0);
    dp_prev[m] = 1;

    vector<long long> dp1_prev(size, 0);

    for (int i = 2; i <= n; ++i) {
        int low = m - (i - 1) * (i - 2) / 2;
        int high = m + (i - 1) * (i - 2) / 2;

        vector<long long> dp_cur(size, 0);
        vector<long long> dp1_cur(size, 0);

        // First DP: dp_cur
        for (int x = low; x <= high; ++x) {
            long long base = dp_prev[x];
            if (base == 0) continue;
            for (int d = -i + 1; d < i; ++d) {
                int idx = x + d;
                int factor = i - abs(d);
                dp_cur[idx] = (dp_cur[idx] + base * factor) % mod;
            }
        }

        // Second DP: dp1_cur
        for (int x = low; x <= high; ++x) {
            dp1_cur[x] = (dp1_prev[x] * i) % mod;
        }
        for (int x = low; x <= high; ++x) {
            long long base = dp_prev[x];
            if (base == 0) continue;
            for (int d = 1; d < i; ++d) {
                int idx = x - d;
                int factor = i - d;
                dp1_cur[idx] = (dp1_cur[idx] + base * factor) % mod;
            }
        }

        dp_prev.swap(dp_cur);
        dp1_prev.swap(dp1_cur);
    }

    long long result = 0;
    for (int j = m + 1; j < size; ++j) {
        result = (result + dp1_prev[j]) % mod;
    }
    cout << result << '\n';

    return 0;
}

