ll solve(int n, ll mod) {
    if (n <= 3) return 0;

    ll last_ans = 17;
    ll ans = 17;
    int size = (n-1)*(n-2)/2 + 1;

    // Two rows for record
    vector<vector<ll>> record(2, vector<ll>(size+1, 0));
    // Initialize the first row for m=3 (since loop starts at m=4)
    record[0][0] = 1;
    record[0][1] = 2;
    record[0][2] = 2;
    record[0][3] = 1;

    int inv = 0;  // current row index (we'll later XOR to toggle)

    for (int m = 4; m < n; ++m) {
        int tp_size = m*(m-1)/2;
        // ans = (m+1) * last_ans, but we take modulo to avoid overflow
        ans = ((ll)(m+1) * last_ans) % mod;

        ll tp = 0;
        // first loop: i from 0 to m-1
        for (int i = 0; i < m; ++i) {
            tp += record[inv^1][i];
            record[inv][i] = tp % mod;
        }
        // second loop: i from m to tp_size/2
        for (int i = m; i <= tp_size/2; ++i) {
            tp += record[inv^1][i];
            tp -= record[inv^1][i-m];
            record[inv][i] = tp % mod;
        }
        // mirror the first half
        for (int i = 0; i <= tp_size/2; ++i) {
            record[inv][tp_size - i] = record[inv][i];
        }

        ll total = 0;
        // loop i from 0 to tp_size-2 (since range(tp_size-1) in Python)
        for (int i = 0; i < tp_size-1; ++i) {
            tp = 0;
            int lower = max(1, -tp_size + i + m + 2);
            for (int j = lower; j <= m; ++j) {
                int idx = m + 2 - j + i;
                // idx should be within [0, tp_size] (verified by problem constraints)
                tp += (ll)j * record[inv][idx];
            }
            total += record[inv][i];
            total %= mod;
            tp %= mod;
            tp = (tp * total) % mod;
            ans = (ans + tp) % mod;
        }

        last_ans = ans;
        inv ^= 1;  // switch row
    }

    return ans % mod;
}

