long long go(int n, int h, map<pair<int,int>, long long>& dp) {
    if (n == 0) return 1;
    if (h == 0) return 0;
    auto key = make_pair(n, h);
    auto it = dp.find(key);
    if (it != dp.end()) return it->second;
    long long sum = 0;
    for (int i = 0; i < n; ++i)
        sum += go(i, h-1, dp) * go(n-1-i, h-1, dp);
    dp[key] = sum;
    return sum;
}

int main() {
    int n, h;
    cin >> n >> h;
    map<pair<int,int>, long long> dp;
    long long result = go(n, n, dp) - go(n, max(0, h-1), dp);
    cout << result << endl;
    return 0;
}

