#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n, h;
    cin >> n >> h;

    // dp[i][j] for 0 <= i,j <= n
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    // base cases
    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) dp[i][0] = 0;
    for (int j = 1; j <= n; ++j) dp[0][j] = 0;

    // pref[i][j] = sum_{k=0}^{j} dp[i][k]
    vector<vector<long long>> pref(n + 1, vector<long long>(n + 1, 0));
    // initialize pref for i=0
    pref[0][0] = dp[0][0];
    for (int j = 1; j <= n; ++j) pref[0][j] = pref[0][j-1] + dp[0][j];

    // fill dp for all i from 1 to n
    for (int i = 1; i <= n; ++i) {
        // compute dp[i][h] for all h >= 1
        for (int hh = 1; hh <= n; ++hh) {
            long long total = 0;
            for (int m = 1; m <= i; ++m) {
                long long part1 = dp[m-1][hh-1] * pref[i-m][hh-1];
                long long part2 = dp[i-m][hh-1];
                if (hh-2 >= 0) {
                    part2 *= pref[m-1][hh-2];
                } else {
                    part2 = 0;
                }
                total += part1 + part2;
            }
            dp[i][hh] = total;
        }
        // update pref for this i
        pref[i][0] = dp[i][0];
        for (int j = 1; j <= n; ++j)
            pref[i][j] = pref[i][j-1] + dp[i][j];
    }

    long long answer = 0;
    for (int i = h; i <= n; ++i) {
        answer += dp[n][i];
    }
    cout << answer << endl;

    return 0;
}

