#include <iostream>
#include <vector>
#include <functional>

int main() {
    int n, h;
    std::cin >> n >> h;

    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(n + 1, -1));
    dp[0][0] = 1;

    std::function<int(int,int)> f;
    f = [&](int n, int h) -> int {
        if (dp[n][h] != -1) {
            return dp[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return f(n, 1);
        }
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            ans += f(n - i - 1, 0) * f(i, h - 1);
            ans += f(n - i - 1, h - 1) * f(i, 0);
            ans -= f(n - i - 1, h - 1) * f(i, h - 1);
        }
        dp[n][h] = ans;
        return ans;
    };

    std::cout << f(n, h) << std::endl;
    return 0;
}

