#include <iostream>
#include <map>
#include <utility>
#include <cmath>
using namespace std;

map<int, int> tab1;
map<pair<int, int>, int> tab2;

int num1(int n) {
    if (n < 0) return 0;
    if (n < 2) return 1;
    if (tab1.find(n) == tab1.end()) {
        int r = 0;
        for (int i = 0; i < n; i++) {
            r += num1(i) * num1(n - 1 - i);
        }
        tab1[n] = r;
    }
    return tab1[n];
}

int num2(int n, int h) {
    if (n < 0 || h <= 0 || n >= (1 << (h - 1))) return 0;
    if (n < 2) return 1;
    if (n < h) return num1(n);
    pair<int, int> key = make_pair(n, h);
    if (tab2.find(key) == tab2.end()) {
        int r = 0;
        for (int i = 0; i < n; i++) {
            r += num2(i, h - 1) * num2(n - 1 - i, h - 1);
        }
        tab2[key] = r;
    }
    return tab2[key];
}

int main() {
    int n, h;
    cin >> n >> h;
    cout << num1(n) - num2(n, h) << endl;
    return 0;
}

